import {
  Group,
  Mesh,
  PlaneGeometry,
  Shape,
  ShapeGeometry,
  BufferGeometry,
  LineBasicMaterial,
  Line,
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  Color,
} from 'three/webgpu';
import { uv, vec2, vec3, vec4, mix, smoothstep, step, fract, min, length, Fn, uniform } from 'three/tsl';
import { gsap } from 'gsap';

// ------------------------------------------------------------------ helpers ----------------------------------------------------------------
function hexToVec3(hex) {
  const c = new Color(hex);
  return vec3(c.r, c.g, c.b);
}

function hexToHex(hex) { return parseInt(hex.slice(1), 16); }

// ------------------------------------------------------------------ main ---------------------------------------------------------------------
export default function createNode(config, ctx) {
  // ----- read config -----------------------------------------------------------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#14141a' }, { at: 1, hex: '#0b0b10' }],
  };
  const primitives = config.cinematicPrimitives ?? [];

  // ----- materials / geometries to dispose --------------------------------------
  const toDispose = [];

  // ----- root group ----------------------------------------------------------------
  const group = new Group();
  // initial position for fade-up (y +0.2)
  group.position.y = 0.2;

  // ------------------------------------------------------------------ background panel --------------------------------------------------------
  const w = 3.2, h = 2.2, r = 0.06;
  const shape = new Shape();
  shape.moveTo(-w / 2 + r, -h / 2);
  shape.lineTo(w / 2 - r, -h / 2);
  shape.quadraticCurveTo(w / 2, -h / 2, w / 2, -h / 2 + r);
  shape.lineTo(w / 2, h / 2 - r);
  shape.quadraticCurveTo(w / 2, h / 2, w / 2 - r, h / 2);
  shape.lineTo(-w / 2 + r, h / 2);
  shape.quadraticCurveTo(-w / 2, h / 2, -w / 2, h / 2 - r);
  shape.lineTo(-w / 2, -h / 2 + r);
  shape.quadraticCurveTo(-w / 2, -h / 2, -w / 2 + r, -h / 2);

  const bgGeom = new ShapeGeometry(shape);
  toDispose.push(bgGeom);
  // background material (basic, gradient + grid)
  const bgMat = new MeshBasicNodeMaterial();
  bgMat.colorNode = Fn(() => {
    const u = uv();
    const cu = u.mul(2).sub(1); // [-1,1]
    const worldX = cu.x.mul(1.6);
    const worldY = cu.y.mul(1.1);
    const dist = length(vec2(worldX, worldY)).div(1.94);
    const grad1 = hexToVec3(colors.gradientStops[0].hex);
    const grad2 = hexToVec3(colors.gradientStops[1].hex);
    const gradient = mix(grad1, grad2, dist);

    // hairline grid
    const pitch = 0.25;
    const gx = fract(worldX.div(pitch));
    const gy = fract(worldY.div(pitch));
    const lineW = 0.006 / pitch; // ≈0.024
    const edgeX = min(gx, (1).sub(gx));
    const edgeY = min(gy, (1).sub(gy));
    const gridLine = step(edgeX, lineW).add(step(edgeY, lineW)).clamp(0, 1);
    const gridCol = hexToVec3(colors.paper);
    const gridBlend = gridLine.mul(0.06);
    const base = mix(gradient, gridCol, gridBlend);

    return vec4(base, 1);
  })();
  const bgMesh = new Mesh(bgGeom, bgMat);
  group.add(bgMesh);

  // border line (hairline 0.006, color #26262f)
  const borderPoints = shape.getPoints(80);
  const borderGeom = new BufferGeometry().setFromPoints(borderPoints.map(p => new ctx.THREE.Vector3(p.x, p.y, 0)));
  toDispose.push(borderGeom);
  const borderMat = new LineBasicMaterial({ color: 0x26262f, transparent: false });
  const borderLine = new Line(borderGeom, borderMat);
  borderLine.position.z = 0.002;
  group.add(borderLine);

  // ------------------------------------------------------------------ ghost preview -----------------------------------------------------------
  const ghostGroup = new Group();
  ghostGroup.position.set(-0.8, 0, 0.01);

  // ghost card outline (1.1 x 1.4, radius 0.04)
  const gw = 1.1, gh = 1.4, gr = 0.04;
  const gShape = new Shape();
  gShape.moveTo(-gw / 2 + gr, -gh / 2);
  gShape.lineTo(gw / 2 - gr, -gh / 2);
  gShape.quadraticCurveTo(gw / 2, -gh / 2, gw / 2, -gh / 2 + gr);
  gShape.lineTo(gw / 2, gh / 2 - gr);
  gShape.quadraticCurveTo(gw / 2, gh / 2, gw / 2 - gr, gh / 2);
  gShape.lineTo(-gw / 2 + gr, gh / 2);
  gShape.quadraticCurveTo(-gw / 2, gh / 2, -gw / 2, gh / 2 - gr);
  gShape.lineTo(-gw / 2, -gh / 2 + gr);
  gShape.quadraticCurveTo(-gw / 2, -gh / 2, -gw / 2 + gr, -gh / 2);
  const ghostCardPoints = gShape.getPoints(60).map(p => new ctx.THREE.Vector3(p.x, p.y, 0));
  const ghostCardGeom = new BufferGeometry().setFromPoints(ghostCardPoints);
  toDispose.push(ghostCardGeom);
  const ghostCardMat = new LineBasicMaterial({ color: 0xe8ecf2, transparent: true, opacity: 0.3 });
  const ghostCardLine = new Line(ghostCardGeom, ghostCardMat);
  ghostGroup.add(ghostCardLine);

  // dial circle (diameter 0.55)
  const dialRadius = 0.275;
  const dialPoints = [];
  const segments = 32;
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    dialPoints.push(new ctx.THREE.Vector3(Math.cos(theta) * dialRadius, Math.sin(theta) * dialRadius, 0));
  }
  const dialGeom = new BufferGeometry().setFromPoints(dialPoints);
  toDispose.push(dialGeom);
  const dialMat = new LineBasicMaterial({ color: 0xe8ecf2, transparent: true, opacity: 0.22 });
  const dialLine = new Line(dialGeom, dialMat);
  ghostGroup.add(dialLine);

  // ghost text bars (two rectangles 0.7 x 0.06)
  const barGeom = new PlaneGeometry(0.7, 0.06);
  toDispose.push(barGeom);
  const barMat = new MeshBasicNodeMaterial();
  barMat.colorNode = Fn(() => {
    const col = hexToVec3(colors.paper);
    return vec4(col, 0.22);
  })();
  const bar1 = new Mesh(barGeom, barMat);
  bar1.position.set(0, 0.2, 0);
  ghostGroup.add(bar1);
  const bar2 = new Mesh(barGeom, barMat);
  bar2.position.set(0, -0.2, 0);
  ghostGroup.add(bar2);

  group.add(ghostGroup);

  // ------------------------------------------------------------------ copy column -------------------------------------------------------------
  const copyGroup = new Group();
  copyGroup.position.set(0.25, 0, 0.01);

  const headline = textItems.find(t => t.role === 'headline')?.text ?? 'Your ledger is empty.';
  const body = textItems.find(t => t.role === 'body')?.text ?? 'Commissioned pieces and saved references will appear here once you begin.';
  const ctaText = textItems.find(t => t.role === 'cta-label')?.text ?? 'BROWSE THE COLLECTION';

  // headline
  const headlineMesh = ctx.fontAtlas.createText(headline, {
    fontSize: 34,
    color: colors.paper,
    align: 'left',
  });
  headlineMesh.position.set(0, 0.2, 0);
  copyGroup.add(headlineMesh);

  // body
  const bodyMesh = ctx.fontAtlas.createText(body, {
    fontSize: 13,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 400,
  });
  bodyMesh.position.set(0, 0.2 - 0.25, 0);
  copyGroup.add(bodyMesh);

  group.add(copyGroup);

  // ------------------------------------------------------------------ CTA button --------------------------------------------------------------
  const btnW = 1.5, btnH = 0.36, btnR = 0.04;
  const btnShape = new Shape();
  btnShape.moveTo(-btnW / 2 + btnR, -btnH / 2);
  btnShape.lineTo(btnW / 2 - btnR, -btnH / 2);
  btnShape.quadraticCurveTo(btnW / 2, -btnH / 2, btnW / 2, -btnH / 2 + btnR);
  btnShape.lineTo(btnW / 2, btnH / 2 - btnR);
  btnShape.quadraticCurveTo(btnW / 2, btnH / 2, btnW / 2 - btnR, btnH / 2);
  btnShape.lineTo(-btnW / 2 + btnR, btnH / 2);
  btnShape.quadraticCurveTo(-btnW / 2, btnH / 2, -btnW / 2, btnH / 2 - btnR);
  btnShape.lineTo(-btnW / 2, -btnH / 2 + btnR);
  btnShape.quadraticCurveTo(-btnW / 2, -btnH / 2, -btnW / 2 + btnR, -btnH / 2);
  const btnGeom = new ShapeGeometry(btnShape);
  toDispose.push(btnGeom);

  // button material: standard with vertical gradient + emissive edge
  const btnMat = new MeshStandardNodeMaterial();
  btnMat.colorNode = Fn(() => {
    const u = uv();
    const top = hexToVec3('#ff4450');
    const bottom = hexToVec3('#c1121f');
    const grad = mix(bottom, top, u.y);
    return vec4(grad, 1);
  })();
  btnMat.emissiveNode = Fn(() => {
    const u = uv();
    const edgeDist = min(min(u.x, 1 - u.x), min(u.y, 1 - u.y)).mul(2); // normalized
    const em = smoothstep(0.02, 0.0, edgeDist).mul(hexToVec3(colors.accent)).mul(1.5);
    return em;
  })();
  btnMat.emissiveIntensity = 1.5;
  const btnMesh = new Mesh(btnGeom, btnMat);
  btnMesh.position.set(0.25, -1.0, 0.01); // placed below copy column
  group.add(btnMesh);

  // CTA label on button
  const ctaLabel = ctx.fontAtlas.createText(ctaText, {
    fontSize: 13,
    color: colors.ink,
    align: 'center',
    letterSpacingPx: 13 * 0.08,
  });
  ctaLabel.position.copy(btnMesh.position);
  ctaLabel.position.z += 0.02;
  group.add(ctaLabel);

  // ------------------------------------------------------------------ animations --------------------------------------------------------------
  const timelines = [];

  // 1) Mount fade-up: all children opacity 0 -> 1, y 0.2 -> 0
  const allChildren = [...group.children];
  const initialMaterials = [];
  allChildren.forEach(child => {
    if (child.isMesh || child.isLine) {
      if (child.material) {
        initialMaterials.push(child.material);
        child.material.transparent = true;
        child.material.opacity = 0;
      }
    }
    if (child.isGroup) {
      child.children.forEach(c => {
        if (c.material) {
          c.material.transparent = true;
          c.material.opacity = 0;
          initialMaterials.push(c.material);
        }
      });
    }
  });

  const tlMount = gsap.timeline();
  tlMount.to(initialMaterials, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });
  tlMount.to(group.position, {
    y: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  }, 0);
  timelines.push(tlMount);

  // 2) Ghost breathing opacity 0.24 -> 0.34 yoyo repeat
  const ghostMats = [];
  ghostGroup.children.forEach(c => {
    if (c.material) {
      ghostMats.push(c.material);
      c.material.opacity = 0.24;
    }
  });
  const tlGhost = gsap.timeline({ repeat: -1, yoyo: true });
  tlGhost.to(ghostMats, {
    opacity: 0.34,
    duration: 2.4,
    ease: 'cubic-bezier(0.445,0.05,0.55,0.95)',
  });
  timelines.push(tlGhost);

  // 3) Press animation on button (triggered on click)
  const tlPress = gsap.timeline({ paused: true });
  const btnGroup = new Group();
  btnGroup.add(btnMesh);
  btnGroup.add(ctaLabel);
  group.add(btnGroup);
  tlPress.to(btnGroup.scale, {
    x: 0.97,
    y: 0.97,
    duration: 0.12,
    ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
  });
  tlPress.to(btnGroup.scale, {
    x: 1,
    y: 1,
    duration: 0.2,
    ease: 'power2.out',
  });
  timelines.push(tlPress);

  // ------------------------------------------------------------------ interactions ------------------------------------------------------------
  group.userData.handlers = {};

  group.userData.handlers.click = (event) => {
    // check if hit on button
    if (event.target === btnMesh || event.target === ctaLabel) {
      tlPress.restart();
      ctx.emit?.('navigate', { to: 'hub-collection' });
    }
  };

  // ------------------------------------------------------------------ cleanup ------------------------------------------------------------------
  group.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    toDispose.forEach(geo => {
      geo.dispose();
    });
    // dispose materials not disposed earlier
    [bgMat, borderMat, ghostCardMat, dialMat, barMat, btnMat].forEach(m => m.dispose());
    // dispose text meshes materials
    [headlineMesh, bodyMesh, ctaLabel].forEach(tm => {
      if (tm && tm.material) tm.material.dispose();
      if (tm && tm.geometry) tm.geometry.dispose();
    });
  };

  return group;
}
